import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { CompanyService } from '../../services/company-service';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';


export interface company {
  id: number
  companyName: string;
  companyAddress: string;
  gstin: string;
  accNo: string;
  bankName: string;
  branchName: string;
  ifsc: string;
  phone: number;

}

@Component({
  selector: 'app-company-master',
  imports: [CommonModule, ReactiveFormsModule, FormsModule, RouterLink],
  templateUrl: './company-master.html',
  styleUrl: './company-master.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CompanyMaster {
Company: company[] = [];
  searchTerm = '';

  constructor(private service: CompanyService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getAllCompanies().subscribe({
      next: (data) => {
        this.Company = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.Company);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredCompanies() {
    const term = this.searchTerm.toLowerCase();
    return this.Company.filter(c =>
      c.companyName.toLowerCase().includes(term) ||
      c.companyAddress.toLowerCase().includes(term) ||
      c.gstin.toLowerCase().includes(term) ||
      c.accNo.toLowerCase().includes(term) ||
      c.bankName.toLowerCase().includes(term) ||
      c.branchName.toLowerCase().includes(term) ||
      c.ifsc.toLowerCase().includes(term) ||
      c.phone.toPrecision().includes(term) 
    );
  }

}

